//! A simulated EMV card for tests and demos (feature `test-card`).
//!
//! It answers INTERNAL AUTHENTICATE the way a DDA card does: it returns SDAD
//! over its ICC dynamic data and the terminal's Unpredictable Number. Its
//! private key is public on purpose (see `tools/gen_test_card.py`), so
//! never enrol it in a wallet that holds real funds.

use crate::bigint;
use crate::sha1;

// 1024-bit, e = 3. Generated by tools/gen_test_card.py.
pub const MODULUS: &str = "b4240d3bf0f41a2aa081123cbc2fd5aa5d2424af0a20dfd9fc23a092563f3e509cb0df2d328c134de6f60dd9a10cb26ceccfa19717e0aa0e2d741810cdef307cee1b297c145fb473ff58429795be626cf9a6939c9a1846a6291a8ab442d0f240d96cae324a32e43ada8e69196b79de3f080a3460585c158b4288b68423cf5587";
pub const EXPONENT: u32 = 3;
pub const PRIVATE_EXPONENT: &str = "781808d2a0a2bc1c6b00b6d3281fe3c6e8c2c31f5c15ea9152c26b0c397f7ee06875ea1e21b2b78944a4093bc0b3219df3351664ba95c6b41e4d6560894a20522a5a8bf75284886f19ec867c0e9d3d33ab8067d32a5f0b6b3587d0f6f13f38a501a28cd480581876678c1084dcb93659e94f4b1b5c99a100d4dd2d4b910932ab";

pub struct TestCard {
    pub modulus: Vec<u8>,
    pub exponent: u32,
    d: Vec<u8>,
    /// Application Transaction Counter, mixed into the ICC dynamic data.
    atc: u16,
}

impl Default for TestCard {
    fn default() -> Self {
        Self { modulus: unhex(MODULUS), exponent: EXPONENT, d: unhex(PRIVATE_EXPONENT), atc: 0 }
    }
}

impl TestCard {
    /// Layout of this card's terminal dynamic data: just the 4-byte UN
    /// (the default DDOL `9F37 04`).
    pub const UN_OFFSET: u8 = 0;
    pub const UN_LEN: u8 = 4;
    pub const TERMINAL_DATA_LEN: u8 = 4;

    /// INTERNAL AUTHENTICATE with `UN = challenge[..4]`. Returns
    /// `(sdad, terminal_data)`.
    pub fn sign_challenge(&mut self, challenge: &[u8; 32]) -> (Vec<u8>, Vec<u8>) {
        let td = challenge[..Self::UN_LEN as usize].to_vec();
        self.atc = self.atc.wrapping_add(1);
        let mut icc_dyn = vec![2];
        icc_dyn.extend_from_slice(&self.atc.to_be_bytes());
        (self.sdad(&icc_dyn, &td), td)
    }

    fn sdad(&self, icc_dyn: &[u8], terminal_data: &[u8]) -> Vec<u8> {
        let n = self.modulus.len();
        let mut body = vec![0x05, 0x01, icc_dyn.len() as u8];
        body.extend_from_slice(icc_dyn);
        body.resize(n - 22, 0xBB);
        let h = sha1::sha1(&[&body, terminal_data]);
        let mut rec = vec![0x6A];
        rec.extend_from_slice(&body);
        rec.extend_from_slice(&h);
        rec.push(0xBC);
        rsa_private(&self.modulus, &self.d, &rec)
    }
}

/// `m^d mod n`, square-and-multiply over the bits of `d`. Not constant time;
/// test use only.
fn rsa_private(n_be: &[u8], d_be: &[u8], m_be: &[u8]) -> Vec<u8> {
    let n = bigint::from_be_bytes(n_be);
    let m = bigint::from_be_bytes(m_be);
    let mut acc = bigint::from_be_bytes(&[1]);
    for byte in d_be {
        for bit in (0..8).rev() {
            acc = bigint::mul_mod(&acc, &acc, &n).unwrap();
            if (byte >> bit) & 1 == 1 {
                acc = bigint::mul_mod(&acc, &m, &n).unwrap();
            }
        }
    }
    bigint::to_be_bytes(&acc, n_be.len()).unwrap()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::emv::{verify_card_challenge, EmvKeyLayout};

    #[test]
    fn signatures_verify() {
        let mut card = TestCard::default();
        let layout = EmvKeyLayout {
            modulus: &card.modulus.clone(),
            exponent: card.exponent,
            un_offset: TestCard::UN_OFFSET,
            un_len: TestCard::UN_LEN,
            terminal_data_len: TestCard::TERMINAL_DATA_LEN,
        };
        let ch = [0x5Au8; 32];
        let (sdad, td) = card.sign_challenge(&ch);
        assert_eq!(verify_card_challenge(&layout, &sdad, &td, &ch), Ok(()));
        let mut other = ch;
        other[0] ^= 1;
        assert!(verify_card_challenge(&layout, &sdad, &td, &other).is_err());
    }
}
